module TopModule (
    input  a,
    input  b,
    input  c,
    input  d,
    output out_sop,
    output out_pos
);

    // Minimum Sum-of-Products (SOP) form for out_sop
    // out_sop is 1 for input values 2, 7, 15
    // Binary representations:
    // 2: 0010 → a=0, b=0, c=1, d=0 → a' b' c d'
    // 7: 0111 → a=0, b=1, c=1, d=1 → a' b c d
    // 15: 1111 → a=1, b=1, c=1, d=1 → a b c d
    // SOP expression: a' b' c d' + a' b c d + a b c d

    assign out_sop = (!a & !b & c & !d) | (!a & b & c & d) | (a & b & c & d);

    // Minimum Product-of-Sums (POS) form for out_pos
    // out_pos is 0 for input values 0, 1, 4, 5, 6, 9, 10, 13, 14
    // Binary representations:
    // 0: 0000 → a=0, b=0, c=0, d=0
    // 1: 0001 → a=0, b=0, c=0, d=1
    // 4: 0100 → a=0, b=1, c=0, d=0
    // 5: 0101 → a=0, b=1, c=0, d=1
