                        dj = (row % 2 == 0) ? (row / 2) : (15 - (row / 2));
                        reg [7:0] ni = (i + di) % 16;
                        reg [7:0] nj = (j + dj) % 16;
                        neighbors += q[(ni*16)+nj];
                    end
                    if (neighbors == 0 || neighbors == 1) begin
                        next_q[(i*16)+j] = 1'b0;
                    end else if (neighbors == 2) begin
                        next_q[(i*16)+j] = current_cell;
                    end else if (neighbors == 3) begin
