    input  s,
    input  w,
    output z
);

typedef enum logic [1:0] {A, B, C, D} state_t;
state_t current_state, next_state;

always_ff @(posedge clk or posedge reset) begin
    if (reset) begin
        current_state <= A;
    end else begin
        current_state <= next_state;
    end
end

always_comb begin
    next_state = current_state;
    case (current_state)
        A: next_state = (s) ? B : A;
        B: begin
            // In state B, we need to check w over the next 3 clock cycles
            // We need to track how many times w was 1 in the last 3 cycles
            // We can use states C, D to track the count of w=1
            if (w) begin
                if (next_state == B) next_state = C;
                else if (next_state == C) next_state = D;
                else if (next_state == D) next_state = B;
            end else begin
                if (next_state == B) next_state = B;
                else if (next_state == C) next_state = B;
                else if (next_state == D) next_state = B;
            end
        end
        C: begin
            if (w) begin
                next_state = D;
            end else begin
                next_state = B;
            end
        end
        D: begin
            if (w) begin
                next_state = B;
            end else begin
                next_state = B;
            end
        end
        default: next_state = A;
    endcase
end

// Logic to determine z
// z is 1 if exactly two of the last three w's were 1
// We track the count of w=1 in states C and D
