    always @(posedge clk or posedge areset) begin
        if (areset) begin
            current_state <= WALK_LEFT;
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
            prev_ground <= 1;
            prev_dig <= 0;
            prev_bump_left <= 0;
            prev_bump_right <= 0;
            original_direction <= 1;
        end else begin
            prev_ground <= ground;
            prev_dig <= dig;
            prev_bump_left <= bump_left;
            prev_bump_right <= bump_right;

            // Determine next state based on priority
            if (dig && prev_ground && !prev_dig && !prev_bump_left && !prev_bump_right) begin
                next_state <= DIGGING;
            end else if (!prev_ground && prev_ground == 1) begin
                next_state <= FALLING;
            end else if (prev_ground && !dig && !prev_bump_left && !prev_bump_right) begin
                if (bump_left) begin
                    next_state <= WALK_RIGHT;
