                next_state <= current_state;
            end else if (dig && prev_ground && !prev_dig && !prev_bump_left && !prev_bump_right) begin
                next_state <= DIGGING;
            end else if (!prev_ground && prev_ground == 1) begin
                next_state <= FALLING;
            end else begin
                next_state <= current_state;
            end

            current_state <= next_state;
        end
    end

    // Output logic
    always @(posedge clk or posedge areset) begin
        if (areset) begin
            walk_left <= 1;
            walk_right <= 0;
            aaah <= 0;
            digging <= 0;
